import React from 'react';
import { useOutletContext, useNavigate } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import './ATSModule.css';

const ATS_P2 = () => {
  const context = useOutletContext();
  const { data: resumeData } = context?.ats || {};
  const navigate = useNavigate();

  if (!resumeData) {
    return (
      <div className="workspace-container">
        <ProjectNavbar basePath="ats" links={["Async", "Skill", "Similarity", "DB"]} />
        <div className="summary-box" style={{ textAlign: 'center', padding: '2rem' }}>
          <h4 style={{ color: '#ef4444' }}>⚠️ No Data Stream Detected in Skill Engine</h4>
          <button onClick={() => navigate('/ats')} className="workspace-button" style={{ backgroundColor: '#2563eb', color: 'white', border: 'none', padding: '0.5rem 1rem', borderRadius: '4px', cursor: 'pointer', marginTop: '1rem' }}>
            Go to Upload Screen
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="ats" links={["Async", "Skill", "Similarity", "DB"]} />
      <div className="summary-box">
        <h3>Skill Vector Graph Analysis</h3>
        <div className="metrics-grid">
          <div className="metric-card">
            <p>IDENTIFIED SKILLS</p>
            <h4>{resumeData.skills_found?.length || 0} Matched</h4>
          </div>
        </div>
        <div style={{ marginTop: '1.5rem' }}>
          <strong>Extracted Skills Inventory:</strong>
          <ul style={{ marginTop: '0.5rem', listStyleType: 'square', paddingLeft: '20px' }}>
            {resumeData.skills_found?.map((skill, idx) => (
              <li key={idx} style={{ color: '#1e293b', padding: '4px 0' }}>{skill}</li>
            )) || <li>No structured skills matched yet.</li>}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default ATS_P2;
